CREATE TABLE IF NOT EXISTS browser_events (id UUID, session_id UUID, event_type LowCardinality(String), path String, source LowCardinality(String), occurred_at DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree ORDER BY id TTL toDateTime(occurred_at)+INTERVAL 90 DAY;
CREATE TABLE IF NOT EXISTS reporting_runs (generation UUID, started_at DateTime64(3,'UTC'), completed_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=MergeTree ORDER BY completed_at TTL toDateTime(completed_at)+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS reporting_order_facts (generation UUID, order_id UUID, customer_id UUID, day Date, status LowCardinality(String), currency LowCardinality(String), total Decimal(24,2), refunded Decimal(24,2), synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,day,order_id) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS reporting_order_items (generation UUID, order_id UUID, product_id UUID, sku String, name String, day Date, currency LowCardinality(String), quantity UInt64, net Decimal(24,2), synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,day,product_id,order_id) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS product_dimensions (generation UUID, product_id UUID, sku String, name String, synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,product_id) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS customer_dimensions (generation UUID, customer_id UUID, registered_on Date, synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,customer_id) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS inventory_snapshot_history (generation UUID, product_id UUID, on_hand Int64, reserved Int64, captured_at DateTime64(3,'UTC')) ENGINE=MergeTree ORDER BY (product_id,captured_at,generation) TTL toDateTime(captured_at)+INTERVAL 90 DAY;
CREATE TABLE IF NOT EXISTS sales_daily (generation UUID, day Date, currency LowCardinality(String), orders UInt64, cancelled UInt64, gross Decimal(24,2), refunds Decimal(24,2), net Decimal(24,2), synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,day,currency) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS product_performance_daily (generation UUID, day Date, product_id UUID, sku String, name String, currency LowCardinality(String), units UInt64, revenue Decimal(24,2), synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,day,product_id,currency) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS customer_ltv (generation UUID, customer_id UUID, currency LowCardinality(String), first_order Date, last_order Date, orders UInt64, value Decimal(24,2), synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,customer_id,currency) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS funnel_daily (generation UUID, day Date, visitors UInt64, carts UInt64, checkouts UInt64, purchases UInt64, synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,day) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS traffic_daily (generation UUID, day Date, source LowCardinality(String), sessions UInt64, synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,day,source) TTL synced_at+INTERVAL 7 DAY;
CREATE TABLE IF NOT EXISTS retention_cohorts (generation UUID, cohort Date, month UInt32, customers UInt64, returning UInt64, synced_at DateTime DEFAULT now()) ENGINE=MergeTree ORDER BY (generation,cohort,month) TTL synced_at+INTERVAL 7 DAY
